def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)
import copy, json
_FIELDS = ("payload", "done", "token", "until", "attempts", "dead")
_ARITY = {"enqueue": (2, 2), "claim": (1, 3), "ack": (2, 2), "retry": (2, 2)}
class Queue:
    def __init__(self, max_attempts=3):
        if not _is_int(max_attempts) or max_attempts <= 0: raise ValueError("max_attempts must be a positive integer")
        self.items = {}; self.serial = 0; self.max_attempts = max_attempts; self.seen = {}
    def enqueue(self, key, payload):
        if key not in self.items:
            self.items[key] = {"payload": payload, "done": False, "token": None, "until": None, "attempts": 0, "dead": False}
    def claim(self, key, now=0, ttl=10):
        if not _is_int(now) or now < 0: raise ValueError("now must be an integer >= 0")
        if not _is_int(ttl) or ttl <= 0: raise ValueError("ttl must be an integer > 0")
        row = self.items.get(key)
        if row is None or row["done"] or row["dead"]: return None
        if row["token"] is not None:
            if row["until"] is None or now < row["until"]: return None
            row["token"] = None; row["until"] = None
        if row["attempts"] >= self.max_attempts:
            row["dead"] = True; return None
        self.serial += 1; row["token"] = self.serial; row["until"] = now + ttl; row["attempts"] += 1
        return row["payload"], self.serial
    def ack(self, key, token):
        row = self.items.get(key)
        if not row or row["done"] or row["dead"] or row["token"] is None or row["token"] != token: return False
        row["done"] = True; return True
    def retry(self, key, token):
        row = self.items.get(key)
        if not row or row["done"] or row["dead"] or row["token"] is None or row["token"] != token: return False
        row["token"] = None; row["until"] = None
        if row["attempts"] >= self.max_attempts: row["dead"] = True
        return True
    def dead(self, key):
        row = self.items.get(key)
        return bool(row and row["dead"])
    def batch(self, keys, now=0, ttl=10):
        if not isinstance(keys, list): raise ValueError("keys must be a list")
        if any(not isinstance(k, str) for k in keys): raise ValueError("keys must be strings")
        if len(set(keys)) != len(keys): raise ValueError("keys must be unique")
        if not _is_int(now) or now < 0: raise ValueError("now must be an integer >= 0")
        if not _is_int(ttl) or ttl <= 0: raise ValueError("ttl must be an integer > 0")
        for k in keys:
            row = self.items.get(k)
            if row is None or row["done"] or row["dead"]: return None
            if row["token"] is not None and (row["until"] is None or now < row["until"]): return None
            if row["attempts"] >= self.max_attempts: return None
        return {k: self.claim(k, now, ttl) for k in keys}
    def dumps(self):
        return json.dumps({"version": 2, "serial": self.serial, "max_attempts": self.max_attempts,
                           "items": {k: {f: r[f] for f in _FIELDS} for k, r in self.items.items()}, "seen": self.seen})
    @classmethod
    def loads(cls, text):
        try: data = json.loads(text)
        except (TypeError, ValueError) as e: raise ValueError("malformed snapshot: %s" % e)
        if not isinstance(data, dict): raise ValueError("snapshot must be an object")
        if not _is_int(data.get("version")) or data["version"] not in (1, 2): raise ValueError("unsupported snapshot version")
        if data["version"] == 1: return cls._from_v1(data)
        for f in ("serial", "max_attempts", "items", "seen"):
            if f not in data: raise ValueError("missing snapshot field: " + f)
        if not _is_int(data["serial"]) or data["serial"] < 0: raise ValueError("invalid serial")
        if not isinstance(data["items"], dict) or not isinstance(data["seen"], dict): raise ValueError("invalid items or seen")
        q = cls(data["max_attempts"]); q.serial = data["serial"]; q.seen = data["seen"]
        for key, r in data["items"].items():
            if not isinstance(r, dict): raise ValueError("invalid item: " + key)
            for f in _FIELDS:
                if f not in r: raise ValueError("missing item field: " + f)
            for f in ("done", "dead"):
                if not isinstance(r[f], bool): raise ValueError("invalid item field: " + f)
            for f in ("token", "until"):
                if r[f] is not None and (not _is_int(r[f]) or r[f] < 0): raise ValueError("invalid item field: " + f)
            if not _is_int(r["attempts"]) or r["attempts"] < 0: raise ValueError("invalid item field: attempts")
            if r["token"] is None and r["until"] is not None: raise ValueError("until requires a token")
            q.items[key] = {f: r[f] for f in _FIELDS}
            if r["token"] is not None: q.serial = max(q.serial, r["token"])
        return q
    @classmethod
    def _from_v1(cls, data):
        for f in ("serial", "items"):
            if f not in data: raise ValueError("missing snapshot field: " + f)
        if not _is_int(data["serial"]) or data["serial"] < 0: raise ValueError("invalid serial")
        if not isinstance(data["items"], dict): raise ValueError("invalid items")
        q = cls(); q.serial = data["serial"]
        for key, r in data["items"].items():
            if not isinstance(r, dict): raise ValueError("invalid item: " + key)
            for f in ("payload", "done", "token"):
                if f not in r: raise ValueError("missing item field: " + f)
            if not isinstance(r["done"], bool): raise ValueError("invalid item field: done")
            if r["token"] is not None and (not _is_int(r["token"]) or r["token"] < 0): raise ValueError("invalid item field: token")
            q.items[key] = {"payload": r["payload"], "done": r["done"], "token": r["token"], "until": None,
                            "attempts": 0 if r["token"] is None else 1, "dead": False}
            if r["token"] is not None: q.serial = max(q.serial, r["token"])
        return q
    def replay(self, events):
        if not isinstance(events, list): raise ValueError("events must be a list")
        saved = copy.deepcopy((self.items, self.serial, self.seen))
        try:
            return [self._apply(e) for e in events]
        except BaseException:
            self.items, self.serial, self.seen = saved
            raise
    def _apply(self, e):
        if not isinstance(e, dict): raise ValueError("event must be an object")
        eid, op, args = e.get("event"), e.get("op"), e.get("args")
        if not isinstance(eid, str): raise ValueError("event id must be a string")
        if op not in _ARITY: raise ValueError("unsupported op")
        if not isinstance(args, list) or not _ARITY[op][0] <= len(args) <= _ARITY[op][1]: raise ValueError("invalid args")
        try: ident = json.loads(json.dumps({"op": op, "args": args}))
        except (TypeError, ValueError) as ex: raise ValueError("event is not JSON serializable: %s" % ex)
        if eid in self.seen:
            if self.seen[eid] != ident: raise ValueError("conflicting event: " + eid)
            return None
        if not isinstance(args[0], str): raise ValueError("key must be a string")
        if op in ("ack", "retry") and not _is_int(args[1]): raise ValueError("token must be an integer")
        result = getattr(self, op)(*args)
        self.seen[eid] = ident
        return result
